package com.fitlife.mfe.comunidade.bff.controller;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.fitlife.mfe.comunidade.bff.service.AuthCookieService;import com.fitlife.mfe.comunidade.bff.service.ComunidadeBffService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/bff/eventos") public class ComunidadeBffController{private final ComunidadeBffService service;private final AuthCookieService auth;private final ObjectMapper mapper;public ComunidadeBffController(ComunidadeBffService s,AuthCookieService a,ObjectMapper m){service=s;auth=a;mapper=m;}@GetMapping public JsonNode listar(@CookieValue(value="FITLIFE_AUTH",required=false)String t){return service.listar(auth.usuarioId(t),t);}@GetMapping("/meus")public JsonNode meus(@CookieValue(value="FITLIFE_AUTH",required=false)String t){return service.meus(auth.usuarioId(t),t);}@PostMapping public JsonNode criar(@RequestBody JsonNode d,@CookieValue(value="FITLIFE_AUTH",required=false)String t){ObjectNode body=d.deepCopy();body.put("usuarioId",auth.usuarioId(t));return service.criar(body,t);}@PutMapping("/{id}")public JsonNode editar(@PathVariable String id,@RequestBody JsonNode d,@CookieValue(value="FITLIFE_AUTH",required=false)String t){ObjectNode body=d.deepCopy();body.put("usuarioId",auth.usuarioId(t));return service.editar(id,body,t);}@PostMapping("/{id}/participacoes")public JsonNode participar(@PathVariable String id,@CookieValue(value="FITLIFE_AUTH",required=false)String t){return service.participar(id,auth.usuarioId(t),t);}}
